(()=>{
'use strict';const $=id=>document.getElementById(id),api=window.ItasoDemo;
const params=new URLSearchParams(location.search),next=api.nextKey(params.get('next'));
let store;try{store=api.createStore(localStorage,sessionStorage,crypto);}catch{}
const accountURL='../cuenta/index.html?next='+next,accessURL='../acceso/index.html?mode=login&next='+next;
if(document.body.dataset.accountPage==='profile'){
 const user=store?.current();if(!user){location.replace(accessURL);return;}
 $('account-loading').hidden=true;$('account-content').hidden=false;$('welcome').textContent=`¡Hola, ${user.name}!`;$('profile-name').textContent=user.name;$('profile-email').textContent=user.email;$('profile-provider').textContent=user.provider==='google-demo'?'Acceso con Google simulado':'Cuenta local de prueba';$('continue').href=api.destination(next);
 $('logout').addEventListener('click',()=>{try{store.logout();location.replace(accessURL);}catch(error){$('account-error').textContent=error.message;}});return;
}
let mode=params.get('mode')==='register'?'register':'login',busy=false;
function render(focus=false){const signup=mode==='register';$('auth-title').textContent=signup?'Crea una cuenta':'Inicia sesión';document.title=$('auth-title').textContent+' · Itaso';$('form-intro').textContent=signup?'Inscríbete':'¡Qué gusto verte de nuevo!';$('name-field').hidden=!signup;$('name').disabled=!signup;$('name').required=signup;$('password').minLength=signup?8:1;$('password').autocomplete=signup?'new-password':'current-password';$('password-hint').textContent=signup?'Al menos 8 caracteres. Usa una contraseña solo para esta prueba.':'La contraseña de tu cuenta de prueba.';$('submit').textContent=signup?'Inscríbete':'Iniciar sesión';$('switch-copy').textContent=signup?'¿Ya tienes una cuenta?':'¿Aún no tienes una cuenta?';$('switch-mode').textContent=signup?'Inicia sesión':'Crea una cuenta';$('form-message').textContent='';$('password').value='';$('password').type='password';$('show-password').textContent='Mostrar';$('show-password').setAttribute('aria-pressed','false');$('show-password').setAttribute('aria-label','Mostrar contraseña');$('nav-login').href='?mode=login&next='+next;const url=new URL(location.href);url.searchParams.set('mode',mode);url.searchParams.set('next',next);history.replaceState(null,'',url);if(focus)$('auth-title').focus();}
function working(value){busy=value;for(const id of ['submit','google-demo','switch-mode'])$(id).disabled=value;$('auth-form').setAttribute('aria-busy',String(value));$('submit').textContent=value?'Un momento…':mode==='register'?'Inscríbete':'Iniciar sesión';}
$('switch-mode').addEventListener('click',()=>{if(busy)return;mode=mode==='login'?'register':'login';render(true);});$('nav-login').addEventListener('click',e=>{e.preventDefault();if(busy)return;mode='login';render(true);});
$('show-password').addEventListener('click',()=>{const reveal=$('password').type==='password';$('password').type=reveal?'text':'password';$('show-password').textContent=reveal?'Ocultar':'Mostrar';$('show-password').setAttribute('aria-label',reveal?'Ocultar contraseña':'Mostrar contraseña');$('show-password').setAttribute('aria-pressed',String(reveal));});
$('auth-form').addEventListener('submit',async e=>{e.preventDefault();if(busy||!$('auth-form').reportValidity())return;working(true);$('form-message').textContent='';try{if(!store)throw Error('Habilita el almacenamiento del navegador para probar las cuentas.');if(mode==='register')await store.register($('name').value,$('email').value,$('password').value);else await store.login($('email').value,$('password').value);$('password').value='';location.assign(accountURL);}catch(error){$('form-message').textContent=error.message;}finally{working(false);}});
$('google-demo').addEventListener('click',()=>{if(busy)return;try{if(!store)throw Error('Habilita el almacenamiento del navegador para probar las cuentas.');store.google();location.assign(accountURL);}catch(error){$('form-message').textContent=error.message;}});
render();
})();
